        "field": "why",
        "before": "Когда начинаете использовать тестирование, даже если не следуете TDD, то все равно начнете задаваться вопросом: \"а как я это буду тестировать?\". И как следствие, будете стараться следовать принципам SOLID, чтобы уменьшить зависимости, упростить методы, что облегчит тестирование. И это приводит к повышению качества кода. Также использую тесты, вы получаете возможность быстро проверить, что изменения кода, не ломают его. На YAxUnit возможно писать юнит, интеграционные и сценарные тесты.",
